-- ---------------------------------------------------------------------------
-- 4. RESOLVE LOOKUPS (existing rows only — nothing created here)
-- ---------------------------------------------------------------------------
UPDATE seed_mfr_stage s
   SET country_code = c.code
  FROM public.countries c
 WHERE c.code = 'IN' AND s.country_name = 'India';

-- State → regions.code, by exact (case-insensitive) name for country IN. No match → NULL.
UPDATE seed_mfr_stage s
   SET region_code = r.code
  FROM (SELECT DISTINCT ON (lower(btrim(name))) lower(btrim(name)) AS lname, code
          FROM public.regions WHERE country_code = 'IN'
         ORDER BY lower(btrim(name)), code) r
 WHERE s.country_code IS NOT NULL AND s.state_name IS NOT NULL
   AND r.lname = lower(s.state_name);

-- Sector → active industry taxonomy term (exact term first, then synonym). No match → NULL.
UPDATE seed_mfr_stage s
   SET industry_id = (
        SELECT tt.id
          FROM public.taxonomy_terms tt
         WHERE tt.term_type = 'industry' AND tt.status = 'active'
           AND (lower(btrim(tt.term)) = lower(s.sector)
                OR lower(s.sector) IN (SELECT lower(btrim(x)) FROM unnest(tt.synonyms::text[]) AS x))
         ORDER BY (lower(btrim(tt.term)) = lower(s.sector)) DESC, tt.created_at, tt.id
         LIMIT 1)
 WHERE s.sector IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 5. DUPLICATE DETECTION (first matching rule wins; matched records are skipped, not merged)
-- ---------------------------------------------------------------------------
-- 5a. Already imported (rerun): same stable research ID in organizations.source_ref
UPDATE seed_mfr_stage s
   SET skip_reason = 'already imported (organizations.source_ref match)', existing_org_id = o.id
  FROM public.organizations o
 WHERE o.source_ref = s.source_ref;

-- 5b. Existing organization with the same published Udyam registration number
UPDATE seed_mfr_stage s
   SET skip_reason = 'existing organization has same Udyam registration_id', existing_org_id = p.organization_id
  FROM public.organization_profiles p
 WHERE s.skip_reason IS NULL AND s.registration_id IS NOT NULL
   AND upper(replace(btrim(p.registration_id), ' ', '')) = s.registration_id;

-- 5c. Existing organization (registered/created outside this import) with the same website domain
UPDATE seed_mfr_stage s
   SET skip_reason = 'existing non-imported organization has same website_domain', existing_org_id = o.id
  FROM public.organizations o
 WHERE s.skip_reason IS NULL AND s.website_domain IS NOT NULL AND o.website_domain IS NOT NULL
   AND (o.source_ref IS NULL OR o.source_ref NOT LIKE 'india_mfr_research:%')
   AND split_part(regexp_replace(lower(btrim(o.website_domain)), '^(https?://)?(www[0-9]?\.)?', ''), '/', 1)
       = s.website_domain;

-- 5d. OPTIONAL — exclude leads whose manufacturing scope the source marks as unconfirmed
--     (7,301 records: association/product leads and FabFlow directory-only listings).
--     Uncomment to import only published-manufacturer-category and published-factory records.
-- UPDATE seed_mfr_stage SET skip_reason = 'excluded by option: manufacturing scope unconfirmed'
--  WHERE skip_reason IS NULL AND manufacturer_status = 'Manufacturing scope unconfirmed';

-- ---------------------------------------------------------------------------
-- 6. INSERTS (FK order: organizations → organization_profiles → facilities → admin_internal_notes)
-- ---------------------------------------------------------------------------
-- 6a. organizations
INSERT INTO public.organizations
       (id, display_name, organization_type, industry_id, description, website_domain, primary_geography,
        status, verification_status, source_ref, record_type, entry_source)
SELECT  new_org_id, display_name, 'manufacturer', industry_id, description, website_domain, primary_geography,
        'claim_pending', 'unverified', source_ref, 'REAL', 'IMPORTED'
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
 ORDER BY company_id;

-- 6b. organization_profiles (1:1, PK = organization_id)
INSERT INTO public.organization_profiles
       (organization_id, registration_id, contact_email, contact_phone, address_line1,
        country_code, region_code, postal_code, company_category, country_name)
SELECT  new_org_id, registration_id, contact_email, contact_phone, address_line1,
        country_code, region_code, postal_code, company_category, country_name
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
 ORDER BY company_id
ON CONFLICT (organization_id) DO NOTHING;

-- 6c. facilities — only where the source publishes the address as a factory / facility.
--     Private + draft, so nothing becomes visible.
INSERT INTO public.facilities
       (organization_id, name, address, address_line1, city, state_province, postal_code,
        country_code, region_code, country_name, visibility, status, is_headquarters)
SELECT  new_org_id, display_name, address_line1, address_line1, city, state_name, postal_code,
        country_code, region_code, country_name, 'private', 'draft', false
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL AND is_factory
 ORDER BY company_id;

-- 6d. admin_internal_notes — research provenance, caveats and published facts that have no
--     dedicated column (contact person, all phones/emails, evidence URLs, review flags …).
--     Not shared with the manufacturer.
INSERT INTO public.admin_internal_notes (manufacturer_id, admin_id, note, shared_with_manufacturer)
SELECT  new_org_id, NULL, internal_note, false
  FROM seed_mfr_stage
 WHERE skip_reason IS NULL
 ORDER BY company_id;

-- 6e. onboarding_source — only if such a column exists in the live DB and accepts 'database_import'
DO $$
DECLARE
  v_has_col  boolean;
  v_defs     text;
BEGIN
  SELECT EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema='public' AND table_name='organizations' AND column_name='onboarding_source')
    INTO v_has_col;
  IF NOT v_has_col THEN
    RAISE NOTICE 'organizations.onboarding_source not present — using entry_source=''IMPORTED'' only';
    RETURN;
  END IF;
  SELECT string_agg(pg_get_constraintdef(oid), ' ') INTO v_defs
    FROM pg_constraint
   WHERE conrelid='public.organizations'::regclass AND contype='c'
     AND pg_get_constraintdef(oid) LIKE '%onboarding_source%';
  IF v_defs IS NOT NULL AND v_defs NOT LIKE '%database_import%' THEN
    RAISE NOTICE 'organizations.onboarding_source exists but does not allow database_import — left unchanged';
    RETURN;
  END IF;
  EXECUTE 'UPDATE public.organizations o SET onboarding_source = ''database_import''
             FROM seed_mfr_stage s WHERE s.skip_reason IS NULL AND o.id = s.new_org_id';
END $$;

-- 6f. OPTIONAL — manufacturer_onboarding draft rows (all schema defaults: status 'draft',
--     step 'personal_information', 0%). Not approved. Leave commented unless your app expects
--     every manufacturer organization to have an onboarding row before it is claimed.
-- INSERT INTO public.manufacturer_onboarding (organization_id)
-- SELECT new_org_id FROM seed_mfr_stage WHERE skip_reason IS NULL
-- ON CONFLICT (organization_id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 7. IN-TRANSACTION ASSERTIONS — any failure rolls back the whole import
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  v_expected int; v_orgs int; v_profiles int; v_notes int; v_fac_expected int; v_fac int;
  v_bad int; v_dupe int; v_members int; v_staged int;
BEGIN
  SELECT count(*) INTO v_staged FROM seed_mfr_stage;
  IF v_staged <> 11214 THEN
    RAISE EXCEPTION 'staged % rows, expected 11214', v_staged;
  END IF;

  SELECT count(*) FILTER (WHERE skip_reason IS NULL),
         count(*) FILTER (WHERE skip_reason IS NULL AND is_factory)
    INTO v_expected, v_fac_expected FROM seed_mfr_stage;

  SELECT count(*) INTO v_orgs     FROM public.organizations o        JOIN seed_mfr_stage s ON s.new_org_id = o.id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_profiles FROM public.organization_profiles p JOIN seed_mfr_stage s ON s.new_org_id = p.organization_id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_fac      FROM public.facilities f           JOIN seed_mfr_stage s ON s.new_org_id = f.organization_id AND s.skip_reason IS NULL;
  SELECT count(*) INTO v_notes    FROM public.admin_internal_notes n JOIN seed_mfr_stage s ON s.new_org_id = n.manufacturer_id AND s.skip_reason IS NULL;

  IF v_orgs <> v_expected OR v_profiles <> v_expected OR v_notes <> v_expected OR v_fac <> v_fac_expected THEN
    RAISE EXCEPTION 'row-count mismatch: expected % orgs/profiles/notes and % facilities; got orgs=% profiles=% notes=% facilities=%',
      v_expected, v_fac_expected, v_orgs, v_profiles, v_notes, v_fac;
  END IF;

  -- imported orgs must be unowned, unapproved, unverified
  SELECT count(*) INTO v_bad
    FROM public.organizations o JOIN seed_mfr_stage s ON s.new_org_id = o.id AND s.skip_reason IS NULL
   WHERE o.status <> 'claim_pending' OR o.verification_status <> 'unverified'
      OR o.created_by_user_id IS NOT NULL OR o.assigned_admin_user_id IS NOT NULL
      OR o.clerk_organization_id IS NOT NULL OR o.entry_source <> 'IMPORTED'
      OR o.organization_type <> 'manufacturer' OR o.is_archived;
  IF v_bad > 0 THEN RAISE EXCEPTION '% imported organizations have unexpected ownership/approval state', v_bad; END IF;

  SELECT count(*) INTO v_members
    FROM public.memberships m JOIN seed_mfr_stage s ON s.new_org_id = m.organization_id AND s.skip_reason IS NULL;
  IF v_members > 0 THEN RAISE EXCEPTION '% memberships reference newly imported organizations', v_members; END IF;

  -- no source_ref may now appear more than once for any record this run inserted
  SELECT count(*) INTO v_dupe FROM (
    SELECT o.source_ref FROM public.organizations o
     WHERE o.source_ref IN (SELECT source_ref FROM seed_mfr_stage WHERE skip_reason IS NULL)
     GROUP BY o.source_ref HAVING count(*) > 1) d;
  IF v_dupe > 0 THEN RAISE EXCEPTION '% duplicate source_ref values would be created', v_dupe; END IF;

  RAISE NOTICE 'seed OK: % organizations, % profiles, % facilities, % internal notes inserted; % skipped',
    v_orgs, v_profiles, v_fac, v_notes, v_staged - v_expected;
END $$;

-- ---------------------------------------------------------------------------
-- 8. RUN SUMMARY (printed before commit)
-- ---------------------------------------------------------------------------
SELECT coalesce(skip_reason, 'inserted') AS outcome, count(*) AS records
  FROM seed_mfr_stage GROUP BY 1 ORDER BY 2 DESC;

SELECT count(*) FILTER (WHERE skip_reason IS NULL)                              AS inserted,
       count(*) FILTER (WHERE skip_reason IS NULL AND industry_id IS NULL)      AS inserted_without_industry_match,
       count(*) FILTER (WHERE skip_reason IS NULL AND state_name IS NOT NULL AND region_code IS NULL) AS inserted_state_without_region_match,
       count(*) FILTER (WHERE skip_reason IS NULL AND is_factory)               AS facilities_created
  FROM seed_mfr_stage;

-- Records skipped because they match an organization that existed before this import
-- (first 500; on a rerun every record shows as 'already imported' and is omitted here)
SELECT company_id, display_name, skip_reason, existing_org_id
  FROM seed_mfr_stage
 WHERE skip_reason IS NOT NULL AND skip_reason NOT LIKE 'already imported%'
 ORDER BY skip_reason, company_id
 LIMIT 500;

COMMIT;

-- =============================================================================
-- 9. POST-COMMIT VALIDATION QUERIES (read-only; safe to run any time)
-- =============================================================================

-- 9.1 Imported organizations by state (expected total on first run = "inserted" above)
SELECT o.status, o.verification_status, o.entry_source, count(*) AS orgs
  FROM public.organizations o
 WHERE o.source_ref LIKE 'india_mfr_research:%'
 GROUP BY 1,2,3 ORDER BY 4 DESC;

-- 9.2 Duplicate check: any research ID imported more than once (expected: 0 rows)
SELECT source_ref, count(*) FROM public.organizations
 WHERE source_ref LIKE 'india_mfr_research:%'
 GROUP BY source_ref HAVING count(*) > 1;

-- 9.3 Imported orgs sharing a website_domain with a non-imported org (expected: 0 rows)
SELECT i.id AS imported_org_id, i.display_name, i.website_domain, e.id AS existing_org_id, e.display_name AS existing_name
  FROM public.organizations i
  JOIN public.organizations e
    ON lower(e.website_domain) = lower(i.website_domain) AND e.id <> i.id
   AND (e.source_ref IS NULL OR e.source_ref NOT LIKE 'india_mfr_research:%')
 WHERE i.source_ref LIKE 'india_mfr_research:%' AND i.created_at > e.created_at;

-- 9.4 Relationship integrity (expected: every count = 0)
SELECT
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%'
      AND NOT EXISTS (SELECT 1 FROM public.organization_profiles p WHERE p.organization_id = o.id))   AS orgs_without_profile,
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%'
      AND NOT EXISTS (SELECT 1 FROM public.admin_internal_notes n WHERE n.manufacturer_id = o.id))    AS orgs_without_note,
  (SELECT count(*) FROM public.organization_profiles p JOIN public.organizations o ON o.id = p.organization_id
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND p.country_code IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.countries c WHERE c.code = p.country_code))                 AS profiles_bad_country,
  (SELECT count(*) FROM public.organizations o
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND o.industry_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.taxonomy_terms t WHERE t.id = o.industry_id AND t.term_type = 'industry')) AS orgs_bad_industry,
  (SELECT count(*) FROM public.facilities f JOIN public.organizations o ON o.id = f.organization_id
    WHERE o.source_ref LIKE 'india_mfr_research:%' AND (f.visibility <> 'private' OR f.status <> 'draft')) AS facilities_not_private_draft;

-- 9.5 Ownership / approval state of imported orgs (claimed or approved later through the app is
--     expected over time; immediately after import every count except the first should be 0)
SELECT count(*)                                                            AS imported_total,
       count(*) FILTER (WHERE o.created_by_user_id IS NOT NULL)            AS with_creator,
       count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.memberships m WHERE m.organization_id = o.id)) AS with_members,
       count(*) FILTER (WHERE o.verification_status <> 'unverified')       AS not_unverified,
       count(*) FILTER (WHERE EXISTS (SELECT 1 FROM public.manufacturer_onboarding mo
                                       WHERE mo.organization_id = o.id AND mo.status = 'approved')) AS onboarding_approved
  FROM public.organizations o
 WHERE o.source_ref LIKE 'india_mfr_research:%';

-- 9.6 Spot-check a few records against the source workbook
SELECT o.source_ref, o.display_name, o.primary_geography, o.website_domain,
       p.contact_email, p.contact_phone, p.postal_code, p.registration_id, p.company_category
  FROM public.organizations o JOIN public.organization_profiles p ON p.organization_id = o.id
 WHERE o.source_ref IN ('india_mfr_research:IN-52A4DA904592', 'india_mfr_research:IN-2131D47F3D02',
                        'india_mfr_research:TN-4143FAC422');
